actual_functions.cp7_credit.native_cent_lines:
create function cp7_credit.native_cent_lines(p_lines jsonb)returns jsonb
language plpgsql immutable security invoker set search_path=''as $$
declare r jsonb;d numeric;c numeric;out_lines jsonb:='[]';
begin
 if jsonb_typeof(p_lines)is distinct from'array'or jsonb_array_length(p_lines)<2 then
  raise exception 'CP7_CREDIT_NATIVE_LINES_ARRAY_REQUIRED';end if;
 for r in select *from jsonb_array_elements(p_lines)loop
  if jsonb_typeof(r)is distinct from'object'then raise exception 'CP7_CREDIT_NATIVE_LINE_OBJECT_REQUIRED';end if;
  d:=coalesce((r->>'debit')::numeric,0);c:=coalesce((r->>'credit')::numeric,0);
  if d::text in('NaN','Infinity','-Infinity')or c::text in('NaN','Infinity','-Infinity')or d<0 or c<0 then
   raise exception 'CP7_CREDIT_NATIVE_FINITE_NONNEGATIVE_MONEY_REQUIRED';end if;
  out_lines:=out_lines||jsonb_build_array(r||jsonb_build_object('debit',round(d,2),'credit',round(c,2)));
 end loop;
 return out_lines;
end $$;

actual_functions.ow04_source_proposal.canonical_json_v1:
create function ow04_source_proposal.canonical_json_v1(p jsonb)returns jsonb
language plpgsql immutable strict security invoker set search_path=''as $$
declare answer jsonb;one record;
begin
 case jsonb_typeof(p)
 when'number'then return to_jsonb(trim_scale((p#>>'{}')::numeric));
 when'array'then
  select coalesce(jsonb_agg(ow04_source_proposal.canonical_json_v1(value)order by ordinal),'[]')into answer
   from jsonb_array_elements(p)with ordinality as x(value,ordinal);return answer;
 when'object'then
  select coalesce(jsonb_object_agg(key,ow04_source_proposal.canonical_json_v1(value)),'{}')into answer from jsonb_each(p);return answer;
 else return p;end case;
end $$;

actual_functions.ow04_source_proposal.cents:
create function ow04_source_proposal.cents(p numeric)returns text
language plpgsql immutable strict security invoker set search_path=''as $$
begin
 if p::text in('NaN','Infinity','-Infinity')or p*100<>trunc(p*100)then
  raise exception 'OW04_SOURCE_EXACT_CENTS_REQUIRED';end if;
 return(case when p<0 then'-'else''end)||trunc(abs(p))::text||'.'||
  lpad(trunc((abs(p)-trunc(abs(p)))*100)::text,2,'0');
end $$;

actual_functions.cp7_credit.current_leaf_assignment:
create function cp7_credit.current_leaf_assignment(p_sale uuid)
returns table(root_sale_id uuid,current_leaf_id uuid,customer_id uuid,requested_status text)
language plpgsql stable security definer set search_path='' as $$
declare roots uuid[];ids uuid[];previous uuid;root uuid;revision bigint:=0;r record;h erp.sales_headers;
begin
 select * into strict h from erp.sales_headers where id=p_sale;
 select array_agg(distinct x.root_sale_id) into roots from cp7_note.revisions x
  where p_sale in(x.root_sale_id,x.previous_sale_id,x.replacement_sale_id);
 if cardinality(roots)>1 then raise exception 'CP7_CREDIT_NOTE_ROOT_AMBIGUOUS';end if;
 root:=coalesce(roots[1],p_sale);previous:=root;ids:=array[root];
 for r in select *from cp7_note.revisions x where x.root_sale_id=root order by x.revision loop
  revision:=revision+1;
  if r.revision<>revision or r.previous_sale_id<>previous or r.replacement_sale_id=any(ids)then
   raise exception 'CP7_CREDIT_NOTE_CHAIN_INVALID';end if;
  ids:=ids||r.replacement_sale_id;previous:=r.replacement_sale_id;
 end loop;
 if not p_sale=any(ids)or exists(select 1 from unnest(ids)x left join erp.sales_headers s on s.id=x
  where s.id is null or s.customer_id is distinct from h.customer_id)then
  raise exception 'CP7_CREDIT_NOTE_MEMBERSHIP_UNPROVEN';end if;
 if h.status in('POSTED','PARTIAL_PAID','PAID')and(p_sale<>previous or exists(
  select 1 from erp.sales_headers s where s.id=any(ids)and s.id<>p_sale
   and s.status in('POSTED','PARTIAL_PAID','PAID')))then
  raise exception 'CP7_CREDIT_ACTIVE_LEAF_AMBIGUOUS';end if;
 return query select root,previous,h.customer_id,h.status::text;
end $$;

actual_functions.cp7_credit.assert_consumer_operation_bou:
create function cp7_credit.assert_consumer_operation_bound_v1(p_operation uuid)returns void
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare o cp7_credit.consumer_operations_v1;c cp7_credit.consumer_execution_context;q cp7_credit.consumer_requests_v1;
 selection jsonb;projection jsonb;period jsonb;
begin
 perform cp7_credit.assert_consumer_operation_input_v1(p_operation);
 select *into strict o from cp7_credit.consumer_operations_v1 where id=p_operation;
 select *into strict c from cp7_credit.consumer_execution_context where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and operation_id=o.id;
 select *into strict q from cp7_credit.consumer_requests_v1 where actor=o.actor and request_id=o.request_id;
 if c.phase not in('LOCKED','POSTING')or q.response is not null
  or(c.actor,c.request_id,c.action,c.payload_sha256,c.quote_sha256,c.authority_snapshot)is distinct from
   (o.actor,o.request_id,o.action,o.payload_sha256,o.quote_sha256,o.authority_snapshot)
  or cp7_credit.consumer_command_access_v1(o.action,o.event_kind)is distinct from o.authority_snapshot
  or cp7_credit.pg_jsonb_sha256(q.payload)<>o.payload_sha256
  or o.locked_sources_sha256<>cp7_credit.pg_jsonb_sha256(o.locked_sources)
  or o.source_graph_sha256<>cp7_credit.pg_jsonb_sha256(o.source_graph)
  or o.projection_sha256<>cp7_credit.pg_jsonb_sha256(o.projection)
  or exists(select 1 from cp7_credit.consumption_events where id=o.id)
  or exists(select 1 from erp.journal_entries where source_id=o.id and source_type in
   ('CP7_CUSTOMER_CREDIT_APPLY','CP7_CUSTOMER_CREDIT_REFUND','CP7_CUSTOMER_CREDIT_EVENT_REVERSE'))then
  raise exception 'CP7_CREDIT_CONSUMER_OWN_LOCKED_OPERATION_REQUIRED';end if;
 perform cp7_credit.assert_no_ambient_native_context();
 select to_jsonb(p)into strict period from erp.accounting_period_control p where singleton_id=1;
 selection:=cp7_credit.consumer_selection_v1(q.payload);
 if selection is distinct from o.locked_sources->'selection'or period is distinct from o.period_snapshot
  or cp7_credit.consumer_joined_graph_v1(o.source_sale_id,o.target_sale_id)is distinct from o.source_graph
  or cp7_credit.consumer_capture_sources_v1(o.source_graph)is distinct from o.locked_sources->'sources'then
  raise exception 'CP7_CREDIT_CONSUMER_LOCKED_SOURCE_CHANGED';end if;
 if o.cash_coa_account_id is not null and cp7_credit.consumer_cash_balance_v1(o.cash_coa_account_id)
  is distinct from(o.projection->>'cash_balance_before')::numeric then raise exception 'CP7_CREDIT_CONSUMER_LOCKED_CASH_CHANGED';end if;
 -- Rebuild reads only already-locked data; it acquires no earlier-order locks.
 projection:=cp7_credit.consumer_projection_v1(q.payload,o.locked_sources);
 if projection is distinct from o.projection or q.expected_versions is distinct from projection->'expected_versions'
  or o.quote_sha256 is distinct from cp7_credit.consumer_quote_binding_v1(q.payload,o.locked_sources,projection)
  or(o.cohort_id,o.customer_id,o.source_sale_id,o.source_root_sale_id,o.source_current_leaf_id,
     o.target_sale_id,o.target_root_sale_id,o.target_current_leaf_id,o.cash_account_id,o.amount,o.restores_event_id)
   is distinct from((selection->>'cohort_id')::uuid,(selection->>'customer_id')::uuid,(selection->>'source_sale_id')::uuid,
     (selection->>'source_root_sale_id')::uuid,(selection->>'source_current_leaf_id')::uuid,(selection->>'target_sale_id')::uuid,
     (selection->>'target_root_sale_id')::uuid,(selection->>'target_current_leaf_id')::uuid,(selection->>'cash_account_id')::uuid,
     (selection->>'amount')::numeric,(selection->>'restores_event_id')::uuid)
  or(o.credit_account_snapshot,o.target_ar_snapshot,o.cash_account_snapshot,o.book_manifest,o.before_native)is distinct from
    (projection->'credit_account',nullif(projection->'target_ar_source','null'::jsonb),nullif(projection->'cash_account','null'::jsonb),
     projection->'book_manifest',projection->'before_native')then
  raise exception 'CP7_CREDIT_CONSUMER_EXACT_SOURCE_PROJECTION_CHANGED';end if;
end $$;

actual_functions.cp7_credit.consumer_verify_posted_journa:
create function cp7_credit.consumer_verify_posted_journal_v1(p_operation uuid,p_journal uuid)returns text
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare o cp7_credit.consumer_operations_v1;j erp.journal_entries;kind text;expected jsonb;actual jsonb;
begin
 select *into strict o from cp7_credit.consumer_operations_v1 where id=p_operation;
 select *into strict j from erp.journal_entries where id=p_journal;
 kind:=case when o.action='UNDO'then'CP7_CUSTOMER_CREDIT_EVENT_REVERSE'
  when o.event_kind='APPLY'then'CP7_CUSTOMER_CREDIT_APPLY'else'CP7_CUSTOMER_CREDIT_REFUND'end;
 if(j.source_type,j.source_id,j.status,j.reversal_of_id,j.economic_date,j.transaction_date)is distinct from
   (kind,o.id,'POSTED',null::uuid,o.economic_date,o.transaction_date)
  or(select count(*)from erp.journal_entries where source_type=kind and source_id=o.id)<>1
  or exists(select 1 from erp.journal_entries where reversal_of_id=j.id or(source_type='JOURNAL_REVERSAL'and source_id=j.id))
  or(select count(*)from erp.journal_lines where journal_entry_id=j.id)<>2
  or exists(select 1 from erp.journal_lines where journal_entry_id=j.id and(vendor_id is not null
   or contractor_id is not null or po_id is not null or product_id is not null))then
  raise exception 'CP7_CREDIT_CONSUMER_POSTED_NATIVE_JOURNAL_CHANGED';end if;
 select jsonb_agg(v order by v->>'account_id'collate"C")into expected
  from jsonb_array_elements(cp7_credit.consumer_operation_lines_v1(o.id))v;
 select jsonb_agg(jsonb_build_object('account_id',l.account_id,'customer_id',l.customer_id,'description',l.description,
  'debit',l.debit,'credit',l.credit)order by l.account_id::text collate"C")into actual
  from erp.journal_lines l where l.journal_entry_id=j.id;
 if actual is distinct from expected then raise exception 'CP7_CREDIT_CONSUMER_POSTED_NATIVE_LINES_CHANGED';end if;
 return cp7_credit.native_lines_sha256(actual);
end $$;

actual_functions.cp7_credit.consumer_actual_manifest_v1:
create function cp7_credit.consumer_actual_manifest_v1(p_operation uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare o cp7_credit.consumer_operations_v1;e cp7_credit.consumption_events;object jsonb;f cp7_credit.financial_materializations;
begin
 select *into strict o from cp7_credit.consumer_operations_v1 where id=p_operation;
 select *into strict e from cp7_credit.consumption_events where id=o.id;
 perform cp7_credit.consumer_event_data_v1(e.id);
 select *into strict f from cp7_credit.financial_materializations where id=o.id;
 object:=cp7_credit.materialized_fact('CONSUMPTION',e.id,jsonb_build_object('event',to_jsonb(e),
  'actual',cp7_credit.materialized_journal_payload(e.journal_id)));
 if(f.root_sale_id,f.actor,f.request_id,f.request_ordinal,f.owning_action,f.payload_sha256,f.source_plan_sha256)
  is distinct from(o.source_root_sale_id,o.actor,o.request_id,1,'CREDIT_'||o.action,o.payload_sha256,o.projection_sha256)
  or f.actual_objects is distinct from jsonb_build_array(object)
  or f.actual_objects_sha256<>cp7_credit.pg_jsonb_sha256(f.actual_objects)
  or not exists(select 1 from cp7_credit.financial_materialization_objects mo where mo.object_kind='CONSUMPTION'
   and mo.object_id=e.id and mo.materialization_id=f.id and mo.fact_sha256=object->>'fact_sha256')
  or(select count(*)from cp7_credit.financial_materialization_objects where materialization_id=f.id)<>1 then
  raise exception 'CP7_CREDIT_CONSUMER_ACTUAL_MATERIALIZATION_CHANGED';end if;
 return jsonb_build_object('contract_version','ow04.consumer-actual-manifest.v1','operation_id',o.id,
  'operation_sha256',cp7_credit.pg_jsonb_sha256(to_jsonb(o)),'consumption_event_id',e.id,
  'journal_id',e.journal_id,'materialization_id',f.id,'actual_objects',f.actual_objects);
end $$;

actual_functions.cp7_credit.consumer_invoice_profile_v1:
create function cp7_credit.consumer_invoice_profile_v1(p_sale uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare h erp.sales_headers;profile jsonb;ar_source jsonb;gross numeric;net numeric;paid numeric;
 effective numeric;actual_ar numeric;issued numeric;incoming numeric;
begin
 if cp7_credit_note_carry_de.is_current_v1(p_sale)then return cp7_credit_note_carry_de.invoice_profile_v1(p_sale);end if;
 select *into strict h from erp.sales_headers where id=p_sale;
 perform cp7_credit.assert_current_materialized_profile(h.id,h.id,h.id);
 profile:=cp7_credit.inspect_current_materialized_profile(h.id,h.id,h.id);
 ar_source:=cp7_credit.consumer_invoice_ar_source_v1(h.id);
 gross:=(ar_source->>'gross_amount')::numeric;
 net:=gross-(select coalesce(sum(i.refund_amount),0)from erp.sales_return_items i join erp.sales_returns r on r.id=i.return_id
  where r.sale_id=h.id and r.status='POSTED');
 select coalesce(sum(amount),0)into paid from erp.sales_payments where sale_id=h.id and status='POSTED';
 issued:=(profile->>'I')::numeric;incoming:=(profile->>'U')::numeric;effective:=paid+incoming-issued;
 actual_ar:=cp7_credit.consumer_document_ar_v1(h.id,h.customer_id,(ar_source->>'account_id')::uuid);
 if net<0 or effective<0 or effective>net or actual_ar is distinct from net-effective
  or h.status is distinct from(case when effective=net then'PAID'when effective>0 then'PARTIAL_PAID'else'POSTED'end)then
  raise exception 'CP7_CREDIT_CONSUMER_FINAL_DOCUMENT_AR_OR_STATUS_CHANGED';end if;
 return jsonb_build_object('sale_id',h.id,'row_version',h.row_version::text,'status',h.status,
  'gross',cp7_credit.cent_text(gross::cp7_credit.cent_amount),'net',cp7_credit.cent_text(net::cp7_credit.cent_amount),
  'P',cp7_credit.cent_text(paid::cp7_credit.cent_amount),'U',cp7_credit.cent_text(incoming::cp7_credit.cent_amount),
  'I',cp7_credit.cent_text(issued::cp7_credit.cent_amount),'E',cp7_credit.cent_text(effective::cp7_credit.cent_amount),
  'AR',cp7_credit.cent_text(actual_ar::cp7_credit.cent_amount),'materialized',profile);
end $$;

actual_functions.cp7_credit.consumer_execute_v1:
create function cp7_credit.consumer_execute_v1(p_request uuid)returns jsonb
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare c cp7_credit.consumer_execution_context;q cp7_credit.consumer_requests_v1;o cp7_credit.consumer_operations_v1;
 locked jsonb;projection jsonb;selection jsonb;binding text;operation uuid:=gen_random_uuid();lines jsonb;kind text;journal uuid;
 line_hash text;event cp7_credit.consumption_events;object jsonb;manifest jsonb;result jsonb;profiles jsonb:='{}';
 final_native jsonb:='{}';sale text;changed uuid[];header erp.sales_headers;net numeric;effective numeric;vectors jsonb;capacity jsonb;
begin
 select *into strict c from cp7_credit.consumer_execution_context where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid()and request_id=p_request;
 select *into strict q from cp7_credit.consumer_requests_v1 where actor=c.actor and request_id=c.request_id;
 if c.phase<>'CLAIMED'or c.operation_id is not null or q.response is not null
  or(c.action,c.payload_sha256,c.quote_sha256)is distinct from(q.action,cp7_credit.pg_jsonb_sha256(q.payload),q.payload->>'quote_sha256')then
  raise exception 'CP7_CREDIT_CONSUMER_PENDING_OUTER_REQUIRED';end if;
 perform cp7_credit.assert_no_ambient_native_context();
 if exists(select 1 from cp7_credit.consumer_posting_scope_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
  raise exception 'CP7_CREDIT_CONSUMER_NESTED_POST_SCOPE';end if;
 locked:=cp7_credit.consumer_lock_sources_v1(q.payload);
 projection:=cp7_credit.consumer_projection_v1(q.payload,locked);selection:=locked->'selection';
 binding:=cp7_credit.consumer_quote_binding_v1(q.payload,locked,projection);
 if binding is distinct from c.quote_sha256 or q.expected_versions is distinct from projection->'expected_versions'
  or locked->'authority'is distinct from c.authority_snapshot then raise exception 'CP7_CREDIT_CONSUMER_REVIEW_CHANGED';end if;
 insert into cp7_credit.consumer_operations_v1(id,actor,actor_app_user_id,request_id,action,event_kind,cohort_id,customer_id,
  source_sale_id,source_root_sale_id,source_current_leaf_id,target_sale_id,target_root_sale_id,target_current_leaf_id,
  cash_account_id,credit_account_id,target_ar_account_id,cash_coa_account_id,amount,restores_event_id,physical_at,economic_date,transaction_date,
  reason,reference,payload_sha256,quote_sha256,source_graph,source_graph_sha256,locked_sources,locked_sources_sha256,
  projection,projection_sha256,period_snapshot,book_manifest,authority_snapshot,credit_account_snapshot,target_ar_snapshot,cash_account_snapshot,before_native)
 values(operation,c.actor,erp.current_app_user_id(),c.request_id,c.action,selection->>'event_kind',(selection->>'cohort_id')::uuid,
  (selection->>'customer_id')::uuid,(selection->>'source_sale_id')::uuid,(selection->>'source_root_sale_id')::uuid,
  (selection->>'source_current_leaf_id')::uuid,(selection->>'target_sale_id')::uuid,(selection->>'target_root_sale_id')::uuid,
  (selection->>'target_current_leaf_id')::uuid,(selection->>'cash_account_id')::uuid,(projection#>>'{credit_account,account,id}')::uuid,
  (projection#>>'{target_ar_source,account_id}')::uuid,(projection#>>'{cash_account,account,id}')::uuid,
  (selection->>'amount')::numeric,(selection->>'restores_event_id')::uuid,(q.payload->>'physical_at')::timestamptz,
  (projection->>'economic_date')::date,(projection->>'transaction_date')::date,q.payload->>'reason',q.payload->>'reference',
  c.payload_sha256,c.quote_sha256,locked->'graph',cp7_credit.pg_jsonb_sha256(locked->'graph'),locked,cp7_credit.pg_jsonb_sha256(locked),
  projection,cp7_credit.pg_jsonb_sha256(projection),locked->'period',projection->'book_manifest',c.authority_snapshot,
  projection->'credit_account',nullif(projection->'target_ar_source','null'::jsonb),nullif(projection->'cash_account','null'::jsonb),projection->'before_native');
 update cp7_credit.consumer_execution_context set phase='LOCKED',operation_id=operation
  where backend_pid=c.backend_pid and transaction_id=c.transaction_id;
 select *into strict o from cp7_credit.consumer_operations_v1 where id=operation;
 perform cp7_credit.assert_consumer_operation_bound_v1(o.id);
 lines:=cp7_credit.consumer_operation_lines_v1(o.id);
 kind:=case when o.action='UNDO'then'CP7_CUSTOMER_CREDIT_EVENT_REVERSE'
  when o.event_kind='APPLY'then'CP7_CUSTOMER_CREDIT_APPLY'else'CP7_CUSTOMER_CREDIT_REFUND'end;
 insert into cp7_credit.consumer_posting_scope_v1 values(c.backend_pid,c.transaction_id,c.actor,c.request_id,o.id,
  kind,o.id,o.economic_date,o.transaction_date,cp7_credit.native_lines_sha256(lines));
 update cp7_credit.consumer_execution_context set phase='POSTING'where backend_pid=c.backend_pid and transaction_id=c.transaction_id;
 journal:=cp7_credit._post_consumer_bound_v1(kind,o.id,o.economic_date,'Pemakaian atau pembatalan kredit pelanggan',lines);
 line_hash:=cp7_credit.consumer_verify_posted_journal_v1(o.id,journal);
 insert into cp7_credit.consumption_events(id,cohort_id,event_kind,amount,economic_date,transaction_date,target_sale_id,
  cash_account_id,restores_event_id,journal_id,source_sha256,lines_sha256_pg,actor,request_id,reason)
 values(o.id,o.cohort_id,o.event_kind,o.amount,o.economic_date,o.transaction_date,o.target_sale_id,o.cash_account_id,
  o.restores_event_id,journal,cp7_credit.pg_jsonb_sha256(to_jsonb(o)),line_hash,o.actor,o.request_id,o.reason);
 select *into strict event from cp7_credit.consumption_events where id=o.id;
 object:=cp7_credit.materialized_fact('CONSUMPTION',event.id,jsonb_build_object('event',to_jsonb(event),
  'actual',cp7_credit.materialized_journal_payload(journal)));
 insert into cp7_credit.financial_materializations(id,root_sale_id,actor,request_id,request_ordinal,owning_action,
  payload_sha256,source_plan_sha256,actual_objects,actual_objects_sha256)
 values(o.id,o.source_root_sale_id,o.actor,o.request_id,1,'CREDIT_'||o.action,o.payload_sha256,o.projection_sha256,
  jsonb_build_array(object),cp7_credit.pg_jsonb_sha256(jsonb_build_array(object)));
 insert into cp7_credit.financial_materialization_objects values('CONSUMPTION',o.id,o.id,object->>'fact_sha256');
 delete from cp7_credit.consumer_posting_scope_v1 where backend_pid=c.backend_pid and transaction_id=c.transaction_id;
 update cp7_credit.consumer_execution_context set phase='MATERIALIZED'where backend_pid=c.backend_pid and transaction_id=c.transaction_id;
 select array_agg(distinct x order by x)into changed from unnest(array[o.source_current_leaf_id,o.target_current_leaf_id])x where x is not null;
 for header in select *from erp.sales_headers where id=any(changed)order by id loop
  net:=(select coalesce(sum(line_total),0)from erp.sales_items where sale_id=header.id)
   -(select coalesce(sum(i.refund_amount),0)from erp.sales_return_items i join erp.sales_returns r on r.id=i.return_id
     where r.sale_id=header.id and r.status='POSTED');
  effective:=cp7_credit.current_effective_paid(header.id);
  if net<0 or effective<0 or effective>net then raise exception 'CP7_CREDIT_CONSUMER_FINAL_EFFECTIVE_PAID_INVALID';end if;
  -- Native bump_row_version/touch and all Native HPP callbacks remain active.
  update erp.sales_headers set status=case when effective=net then'PAID'when effective>0 then'PARTIAL_PAID'else'POSTED'end where id=header.id;
 end loop;
 for sale in select value from jsonb_array_elements_text(cp7_credit_note_carry_de.active_sales_v1(o.source_graph))order by value loop
  profiles:=profiles||jsonb_build_object(sale,cp7_credit.consumer_invoice_profile_v1(sale::uuid));
  final_native:=final_native||jsonb_build_object(sale,cp7_credit.consumer_native_invariant_v1(sale::uuid));
  if final_native->sale is distinct from o.before_native->sale then
   raise exception 'CP7_CREDIT_CONSUMER_CHANGED_NATIVE_STOCK_HPP_OR_PAYMENT';end if;
  if(profiles#>>array[sale,'row_version'])::bigint is distinct from
   ((o.projection#>>array['expected_versions',sale])::bigint+case when sale::uuid=any(changed)then 1 else 0 end)then
   raise exception 'CP7_CREDIT_CONSUMER_REVIEW_EPOCH_NOT_RETIRED_EXACTLY';end if;
 end loop;
 vectors:=cp7_credit.consumer_source_vectors_v1(o.cohort_id);
 capacity:=ow04_pure_kernel.credit_capacity_v1(vectors->'recognition',vectors->'consumptions',o.economic_date::text,o.transaction_date::text);
 if capacity->'source_prefixes_nonnegative'is distinct from'true'::jsonb then raise exception 'CP7_CREDIT_CONSUMER_FINAL_CAPACITY_UNFUNDED';end if;
 if o.cash_coa_account_id is not null then perform cp7_guard.check_cash(o.cash_coa_account_id,o.economic_date,o.transaction_date);end if;
 if o.cash_coa_account_id is not null and cp7_credit.consumer_cash_balance_v1(o.cash_coa_account_id)
  is distinct from (o.projection->>'cash_balance_before')::numeric-o.amount then
  raise exception 'CP7_CREDIT_CONSUMER_EXACT_CASH_EFFECT_CHANGED';end if;
 perform cp7_credit.credit_account_facts_v1(o.credit_account_id);
 if cp7_credit.consumer_command_access_v1(o.action,o.event_kind)is distinct from o.authority_snapshot then
  raise exception using errcode='42501',message='CP7_CREDIT_CONSUMER_FINAL_ACCESS_CHANGED';end if;
 manifest:=cp7_credit.consumer_actual_manifest_v1(o.id);
 result:=cp7_credit.consumer_outcome_v1(o.id,profiles,capacity);
 insert into cp7_credit.consumer_completions_v1(operation_id,consumption_event_id,journal_id,materialization_id,journal_lines_sha256_pg,
  actual_manifest,actual_manifest_sha256,final_native,final_profiles,response)
 values(o.id,o.id,journal,o.id,line_hash,manifest,cp7_credit.pg_jsonb_sha256(manifest),final_native,
  jsonb_build_object('invoices',profiles,'source_capacity',capacity,'cash_balance_after',case when o.cash_coa_account_id is not null then
   cp7_credit.cent_text(cp7_credit.consumer_cash_balance_v1(o.cash_coa_account_id)::cp7_credit.cent_amount)end),result);
 update cp7_credit.consumer_execution_context set phase='COMPLETE'where backend_pid=c.backend_pid and transaction_id=c.transaction_id;
 return result;
end $$;

actual_functions.cp7_credit.consumer_invoice_ar_source_v1:
create function cp7_credit.consumer_invoice_ar_source_v1(p_sale uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare h erp.sales_headers;j erp.journal_entries;account uuid;gross numeric;
begin
 select *into strict h from erp.sales_headers where id=p_sale;
 select coalesce(sum(i.line_total),0)into gross from erp.sales_items i where i.sale_id=p_sale;
 select *into strict j from erp.journal_entries where source_type='SALE'and source_id=p_sale and reversal_of_id is null;
 if gross<=0 or gross::text in('NaN','Infinity','-Infinity')or gross*100<>trunc(gross*100)
  or j.status not in('POSTED','REVERSED')or j.economic_date is distinct from(h.sale_date at time zone'Asia/Jakarta')::date
  or j.transaction_date<j.economic_date then raise exception 'CP7_CREDIT_CONSUMER_TARGET_SALE_SOURCE_INVALID';end if;
 select l.account_id into strict account from erp.journal_lines l join erp.chart_accounts a on a.id=l.account_id
  where l.journal_entry_id=j.id and l.customer_id=h.customer_id and l.debit=gross and l.credit=0
   and l.vendor_id is null and l.contractor_id is null and l.po_id is null and l.product_id is null
   and a.account_type='ASSET'and a.normal_balance='DEBIT'
   and not exists(select 1 from erp.cash_accounts c where c.coa_account_id=a.id);
 if(select count(*)from erp.journal_lines l where l.journal_entry_id=j.id and l.account_id=account)<>1 then
  raise exception 'CP7_CREDIT_CONSUMER_TARGET_AR_SOURCE_AMBIGUOUS';end if;
 return jsonb_build_object('sale_id',h.id,'customer_id',h.customer_id,'account_id',account,
  'gross_amount',cp7_credit.cent_text(gross::cp7_credit.cent_amount),
  'sale_journal_id',j.id,'financial_source',ow04_source_proposal.financial_journal_payload(j.id,account));
end $$;

actual_functions.cp7_credit.consumer_operation_lines_v1:
create function cp7_credit.consumer_operation_lines_v1(p_operation uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare o cp7_credit.consumer_operations_v1;other_account uuid;label text;
begin
 select *into strict o from cp7_credit.consumer_operations_v1 where id=p_operation;
 other_account:=case o.event_kind when'APPLY'then o.target_ar_account_id else o.cash_coa_account_id end;
 if other_account is null or other_account=o.credit_account_id then
  raise exception 'CP7_CREDIT_CONSUMER_ACCOUNT_COLLISION';end if;
 label:=case o.action when'UNDO'then'Pembatalan pemakaian kredit pelanggan'
  when'APPLY'then'Pemakaian kredit pelanggan pada nota'else'Pengembalian kredit pelanggan'end;
 return cp7_credit.native_cent_lines(jsonb_build_array(
  jsonb_build_object('account_id',o.credit_account_id,'customer_id',o.customer_id,
   'description',label,'debit',greatest(o.amount,0),'credit',greatest(-o.amount,0)),
  jsonb_build_object('account_id',other_account,'customer_id',o.customer_id,
   'description',label,'debit',greatest(-o.amount,0),'credit',greatest(o.amount,0))));
end $$;

actual_functions.cp7_credit.consumer_event_data_v1:
create function cp7_credit.consumer_event_data_v1(p_event uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare e cp7_credit.consumption_events;o cp7_credit.consumer_operations_v1;
 ch cp7_credit.cohorts;rf cp7_credit.return_families;j erp.journal_entries;
 old cp7_credit.consumption_events;initial cp7_credit.initial_refund_operations;
 m cp7_credit.initial_return_materializations;expected jsonb;actual jsonb;
 source_kind text;line_hash text;old_data jsonb;node uuid;assignment record;
begin
 select *into strict e from cp7_credit.consumption_events where id=p_event;
 select *into strict ch from cp7_credit.cohorts where id=e.cohort_id;
 select *into strict rf from cp7_credit.return_families where id=ch.family_id;
 select *into strict j from erp.journal_entries where id=e.journal_id;
 select *into o from cp7_credit.consumer_operations_v1 where id=e.id;
 if o.id is null then
  -- The existing initial refund is retained as its original immutable fact.
  -- Later consumer history does not make that historical receipt expire.
  select *into strict initial from cp7_credit.initial_refund_operations where id=e.id;
  select *into strict m from cp7_credit.initial_return_materializations where refund_operation_id=initial.id;
  if (e.cohort_id,e.event_kind,e.amount,e.target_sale_id,e.cash_account_id,e.restores_event_id,
      e.actor,e.request_id,e.economic_date,e.transaction_date,e.source_sha256)
   is distinct from(initial.cohort_id,'REFUND',initial.full_amount,null::uuid,initial.cash_account_id,null::uuid,
      initial.actor,initial.request_id,(initial.physical_at at time zone'Asia/Jakarta')::date,
      initial.required_book_floor,cp7_credit.pg_jsonb_sha256(to_jsonb(initial)))
   or e.reason is distinct from initial.reason
   or m.cohort_id<>ch.id or initial.initial_plan_id<>ch.initial_plan_id
   or initial.full_amount<>ch.initial_net_amount
   or initial.book_floor_manifest is distinct from m.projection->'refund_book_plan'
   or e.lines_sha256_pg is distinct from cp7_credit.verify_initial_refund_journal(initial.id,j.id,e.transaction_date)then
   raise exception 'CP7_CREDIT_INITIAL_CONSUMER_DATA_CHANGED';end if;
  return jsonb_build_object('event_id',e.id,'operation_origin','INITIAL_REFUND',
   'event',to_jsonb(e),'journal_id',j.id,'credit_account_id',ch.credit_account_id,
   'other_account_id',(initial.cash_account_snapshot#>>'{account,id}')::uuid,
   'customer_id',ch.customer_id,'actual_data_verified',true,
   'complete_financial_operation_proven',false);
 end if;
 if (e.cohort_id,e.event_kind,e.amount,e.target_sale_id,e.cash_account_id,e.restores_event_id,
     e.actor,e.request_id,e.economic_date,e.transaction_date,e.reason,e.source_sha256)
  is distinct from(o.cohort_id,o.event_kind,o.amount,o.target_sale_id,o.cash_account_id,o.restores_event_id,
     o.actor,o.request_id,o.economic_date,o.transaction_date,o.reason,cp7_credit.pg_jsonb_sha256(to_jsonb(o)))
  or(o.customer_id,o.credit_account_id,o.source_sale_id,o.source_root_sale_id)is distinct from
    (ch.customer_id,ch.credit_account_id,ch.source_sale_id,rf.family_root_sale_id)
  or o.source_graph_sha256 is distinct from cp7_credit.pg_jsonb_sha256(o.source_graph)
  or o.locked_sources_sha256 is distinct from cp7_credit.pg_jsonb_sha256(o.locked_sources)
  or o.projection_sha256 is distinct from cp7_credit.pg_jsonb_sha256(o.projection)
  or o.credit_account_snapshot#>>'{account,id}'is distinct from o.credit_account_id::text
  or (o.action='UNDO')is distinct from(o.amount<0)
  or o.amount=0 or o.amount::text in('NaN','Infinity','-Infinity')or o.amount*100<>trunc(o.amount*100)
  or o.economic_date is distinct from(o.physical_at at time zone'Asia/Jakarta')::date
  or not isfinite(o.physical_at)or not isfinite(o.economic_date)or not isfinite(o.transaction_date)
  or o.transaction_date<o.economic_date then
  raise exception 'CP7_CREDIT_CONSUMER_OPERATION_DATA_CHANGED';end if;
 -- Root identity is stable history. A lawful later correction may change the
 -- current leaf; do not compare that new leaf with an old operation's leaf.
 foreach node in array array[o.source_sale_id,o.source_current_leaf_id]loop
  select *into strict assignment from cp7_credit.current_leaf_assignment(node);
  if(assignment.root_sale_id,assignment.customer_id)is distinct from(o.source_root_sale_id,o.customer_id)then
   raise exception 'CP7_CREDIT_CONSUMER_SOURCE_ROOT_CHANGED';end if;
 end loop;
 if o.event_kind='APPLY'then
  if o.target_sale_id is null or o.target_sale_id is distinct from o.target_current_leaf_id
   or o.target_root_sale_id=o.source_root_sale_id
   or o.target_ar_account_id=o.credit_account_id
   or o.target_ar_snapshot->>'account_id'is distinct from o.target_ar_account_id::text
   or o.target_ar_snapshot is distinct from cp7_credit.consumer_invoice_ar_source_v1(o.target_sale_id)
   or o.cash_account_id is not null or o.cash_coa_account_id is not null or o.cash_account_snapshot is not null then
   raise exception 'CP7_CREDIT_CONSUMER_TARGET_DATA_CHANGED';end if;
  foreach node in array array[o.target_sale_id,o.target_current_leaf_id]loop
   select *into strict assignment from cp7_credit.current_leaf_assignment(node);
   if(assignment.root_sale_id,assignment.customer_id)is distinct from(o.target_root_sale_id,o.customer_id)then
    raise exception 'CP7_CREDIT_CONSUMER_TARGET_ROOT_CHANGED';end if;
  end loop;
 else
  if o.cash_account_id is null or o.cash_coa_account_id is null or o.cash_coa_account_id=o.credit_account_id
   or o.cash_account_snapshot#>>'{cash,id}'is distinct from o.cash_account_id::text
   or o.cash_account_snapshot#>>'{cash,coa_account_id}'is distinct from o.cash_coa_account_id::text
   or o.cash_account_snapshot#>>'{account,id}'is distinct from o.cash_coa_account_id::text
   or o.target_sale_id is not null or o.target_root_sale_id is not null
   or o.target_current_leaf_id is not null or o.target_ar_account_id is not null or o.target_ar_snapshot is not null then
   raise exception 'CP7_CREDIT_CONSUMER_CASH_DATA_CHANGED';end if;
 end if;
 if o.action='UNDO'then
  select *into strict old from cp7_credit.consumption_events where id=o.restores_event_id;
  if old.amount<=0 or(e.cohort_id,e.event_kind,e.amount,e.cash_account_id)
    is distinct from(old.cohort_id,old.event_kind,-old.amount,old.cash_account_id)
   or not cp7_credit_note_carry_de.same_target_v1(old.target_sale_id,e.target_sale_id)
   or e.economic_date<old.economic_date or e.transaction_date<old.transaction_date
   or(select count(*)from cp7_credit.consumption_events where restores_event_id=old.id)<>1 then
   raise exception 'CP7_CREDIT_CONSUMER_NAMED_UNDO_CHANGED';end if;
  old_data:=cp7_credit.consumer_event_data_v1(old.id);
  if(old_data->>'credit_account_id',old_data->>'other_account_id',old_data->>'customer_id')is distinct from
    (o.credit_account_id::text,coalesce(o.target_ar_account_id,o.cash_coa_account_id)::text,o.customer_id::text)then
   raise exception 'CP7_CREDIT_CONSUMER_UNDO_ACCOUNT_CHANGED';end if;
  source_kind:='CP7_CUSTOMER_CREDIT_EVENT_REVERSE';
 else
  if o.restores_event_id is not null or o.action is distinct from o.event_kind then
   raise exception 'CP7_CREDIT_CONSUMER_POSITIVE_DATA_CHANGED';end if;
  source_kind:=case o.event_kind when'APPLY'then'CP7_CUSTOMER_CREDIT_APPLY'else'CP7_CUSTOMER_CREDIT_REFUND'end;
 end if;
 if(j.source_type,j.source_id,j.status,j.reversal_of_id,j.economic_date,j.transaction_date)is distinct from
   (source_kind,o.id,'POSTED',null::uuid,o.economic_date,o.transaction_date)
  or(select count(*)from erp.journal_entries where source_type=source_kind and source_id=o.id)<>1
  or exists(select 1 from erp.journal_entries where reversal_of_id=j.id or(source_type='JOURNAL_REVERSAL'and source_id=j.id))
  or(select count(*)from erp.journal_lines where journal_entry_id=j.id)<>2
  or exists(select 1 from erp.journal_lines where journal_entry_id=j.id and(vendor_id is not null
   or contractor_id is not null or po_id is not null or product_id is not null))then
  raise exception 'CP7_CREDIT_CONSUMER_ACTUAL_JOURNAL_CHANGED';end if;
 select jsonb_agg(x order by x->>'account_id'collate"C")into expected
  from jsonb_array_elements(cp7_credit.consumer_operation_lines_v1(o.id))x;
 select jsonb_agg(jsonb_build_object('account_id',l.account_id,'customer_id',l.customer_id,'description',l.description,
  'debit',l.debit,'credit',l.credit)order by l.account_id::text collate"C")into actual
  from erp.journal_lines l where l.journal_entry_id=j.id;
 line_hash:=cp7_credit.native_lines_sha256(actual);
 if actual is distinct from expected or e.lines_sha256_pg is distinct from line_hash then
  raise exception 'CP7_CREDIT_CONSUMER_ACTUAL_LINES_CHANGED';end if;
 return jsonb_build_object('event_id',e.id,'operation_origin','CONSUMER_COMMAND',
  'event',to_jsonb(e),'journal_id',j.id,'credit_account_id',o.credit_account_id,
  'other_account_id',coalesce(o.target_ar_account_id,o.cash_coa_account_id),
  'customer_id',o.customer_id,'actual_data_verified',true,
  'complete_financial_operation_proven',false);
end $$;

actual_functions.cp7_credit.consumer_incoming_funding_v1:
create function cp7_credit.consumer_incoming_funding_v1(p_sale uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare e cp7_credit.consumption_events;fact jsonb;events jsonb:='[]';
begin
 for e in select *from cp7_credit.consumption_events where event_kind='APPLY'and cp7_credit_note_carry_de.effective_target_v1(id)=p_sale order by id loop
  fact:=cp7_credit.consumer_event_data_v1(e.id);
  events:=events||jsonb_build_array(jsonb_build_object('id','journal:'||e.journal_id::text,'kind','FUNDING',
   'amount',cp7_credit.cent_text(e.amount),'economic_date',e.economic_date::text,
   'transaction_date',e.transaction_date::text,'source_sha256',ow04_source_proposal.sha(
    ow04_source_proposal.financial_journal_payload(e.journal_id,(fact->>'other_account_id')::uuid))));
 end loop;
 select coalesce(jsonb_agg(x order by x->>'id'collate"C"),'[]')into events from jsonb_array_elements(events)x;
 return events;
end $$;

actual_functions.cp7_credit.validate_consumer_payload_v1:
create function cp7_credit.validate_consumer_payload_v1(p jsonb,p_quote_required boolean)returns void
language plpgsql immutable security invoker set search_path=''as $$
declare key text;physical timestamptz;required text[]:=array['action','cohort_id','target_sale_id','cash_account_id',
 'restores_event_id','amount','physical_at','reason','reference'];
begin
 if p_quote_required is null then raise exception 'CP7_CREDIT_CONSUMER_PAYLOAD_FIELDS';end if;
 if p_quote_required then required:=array_append(required,'quote_sha256');end if;
 if jsonb_typeof(p)is distinct from'object'or not p?&required or p-required<>'{}'::jsonb
  or p->>'action'is null or p->>'action'not in('APPLY','REFUND','UNDO')then
  raise exception 'CP7_CREDIT_CONSUMER_PAYLOAD_FIELDS';end if;
 foreach key in array required loop
  if jsonb_typeof(p->key)not in('string','null')then raise exception 'CP7_CREDIT_CONSUMER_PAYLOAD_FIELDS';end if;
 end loop;
 if jsonb_typeof(p->'reason')is distinct from'string'or p->>'reason'<>btrim(p->>'reason')
  or length(p->>'reason')not between 5 and 1000
  or jsonb_typeof(p->'physical_at')is distinct from'string'or btrim(p->>'physical_at')=''
  or (p->>'physical_at')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
  or p->>'reference'is not null and(length(p->>'reference')>100 or p->>'reference'<>btrim(p->>'reference'))
  or p_quote_required and(p->>'quote_sha256'is null or p->>'quote_sha256'!~'^[0-9a-f]{64}$')then
  raise exception 'CP7_CREDIT_CONSUMER_PAYLOAD_FIELDS';end if;
 physical:=(p->>'physical_at')::timestamptz;
 if not isfinite(physical)then raise exception 'CP7_CREDIT_CONSUMER_EXPLICIT_PHYSICAL_REQUIRED';end if;
 foreach key in array array['cohort_id','target_sale_id','cash_account_id','restores_event_id']loop
  if p->>key is not null and p->>key!~'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'then
   raise exception 'CP7_CREDIT_CONSUMER_PAYLOAD_FIELDS';end if;
 end loop;
 if p->>'action'='UNDO'then
  if p->>'restores_event_id'is null or p->>'cohort_id'is not null or p->>'target_sale_id'is not null
   or p->>'cash_account_id'is not null or p->>'amount'is not null then
   raise exception 'CP7_CREDIT_CONSUMER_UNDO_NAMES_ORIGINAL_ONLY';end if;
 else
  if p->>'cohort_id'is null or p->>'restores_event_id'is not null
   or p->>'amount'is null or p->>'amount'!~'^(0|[1-9][0-9]*)\.[0-9]{2}$'
   or(p->>'amount')::numeric<=0
   or(p->>'action'='APPLY')is distinct from(p->>'target_sale_id'is not null)
   or(p->>'action'='REFUND')is distinct from(p->>'cash_account_id'is not null)then
   raise exception 'CP7_CREDIT_CONSUMER_EXACT_POSITIVE_CHOICE_REQUIRED';end if;
 end if;
end $$;

actual_functions.cp7_credit.consumer_payload_kind_v1:
create function cp7_credit.consumer_payload_kind_v1(p jsonb)returns text
language plpgsql stable security definer set search_path=''as $$
declare e cp7_credit.consumption_events;a jsonb;
begin
 -- Read no private selector before the current common sales/AR read gate.
 a:=erp.get_my_access_v1();
 if auth.uid()is null or auth.jwt()->>'role'is distinct from'authenticated'
  or a->'allowed'is distinct from'true'::jsonb or not erp.has_permission('sales.invoice.view')
  or not erp.has_permission('finance.ar.view')then
  raise exception using errcode='42501',message='CP7_SALES_ACCESS_DENIED';end if;
 if p->>'action'='UNDO'then
  select *into strict e from cp7_credit.consumption_events where id=(p->>'restores_event_id')::uuid;
  if e.amount<=0 or e.restores_event_id is not null then raise exception 'CP7_CREDIT_CONSUMER_POSITIVE_ORIGINAL_REQUIRED';end if;
  return e.event_kind;
 end if;
 return p->>'action';
end $$;

actual_functions.cp7_credit.consumer_internal_allowed_v1:
create function cp7_credit.consumer_internal_allowed_v1()returns boolean
language plpgsql volatile security definer set search_path=''set TimeZone='UTC'as $$
declare c cp7_credit.consumer_execution_context;q cp7_credit.consumer_requests_v1;o cp7_credit.consumer_operations_v1;
begin
 if current_setting('transaction_isolation')<>'read committed'or auth.uid()is null
  or auth.jwt()->>'role'is distinct from'authenticated'then
  raise exception using errcode='42501',message='CP7_CREDIT_CONSUMER_CURRENT_ACTOR_REQUIRED';end if;
 select *into strict c from cp7_credit.consumer_execution_context where backend_pid=pg_backend_pid()
  and transaction_id=txid_current()and actor=auth.uid();
 select *into strict q from cp7_credit.consumer_requests_v1 where actor=c.actor and request_id=c.request_id;
 select *into strict o from cp7_credit.consumer_operations_v1 where id=c.operation_id;
 if c.phase not in('LOCKED','POSTING','MATERIALIZED','COMPLETE')or q.response is not null
  or(c.actor,c.request_id,c.action,c.payload_sha256,c.quote_sha256,c.authority_snapshot)is distinct from
    (o.actor,o.request_id,o.action,o.payload_sha256,o.quote_sha256,o.authority_snapshot)
  or q.action<>o.action or cp7_credit.pg_jsonb_sha256(q.payload)<>o.payload_sha256
  or o.actor_app_user_id is distinct from erp.current_app_user_id()
  or q.payload->>'quote_sha256'<>o.quote_sha256
  or cp7_credit.consumer_command_access_v1(o.action,o.event_kind)is distinct from o.authority_snapshot then
  raise exception using errcode='42501',message='CP7_CREDIT_CONSUMER_OWN_CURRENT_SCOPE_REQUIRED';end if;
 -- Do not call source/HPP collectors from require_internal's own dispatch:
 -- those Native readers can call require_internal themselves. This branch
 -- proves genuine pending typed operation ownership and current permissions;
 -- the poster's separate bound callback proves the full financial source.
 return true;
end $$;

actual_functions.cp7_credit.assert_consumer_closed_v1:
create function cp7_credit.assert_consumer_closed_v1(p_operation uuid)returns void
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare o cp7_credit.consumer_operations_v1;c cp7_credit.consumer_completions_v1;q cp7_credit.consumer_requests_v1;
 e cp7_credit.consumption_events;manifest jsonb;expected jsonb;profiles jsonb;profile jsonb;before_profile jsonb;native jsonb;
 sale text;net numeric;paid numeric;incoming numeric;issued numeric;effective numeric;after_version bigint;vectors jsonb;capacity jsonb;
begin
 perform cp7_credit.assert_consumer_operation_input_v1(p_operation);
 select *into strict o from cp7_credit.consumer_operations_v1 where id=p_operation;
 select *into strict c from cp7_credit.consumer_completions_v1 where operation_id=o.id;
 select *into strict q from cp7_credit.consumer_requests_v1 where actor=o.actor and request_id=o.request_id;
 select *into strict e from cp7_credit.consumption_events where id=o.id;
 manifest:=cp7_credit.consumer_actual_manifest_v1(o.id);
 profiles:=c.final_profiles->'invoices';
 expected:=cp7_credit.consumer_outcome_v1(o.id,profiles,c.final_profiles->'source_capacity');
 if(q.action,q.payload->>'quote_sha256',cp7_credit.pg_jsonb_sha256(q.payload),q.expected_versions,q.response)
   is distinct from(o.action,o.quote_sha256,o.payload_sha256,o.projection->'expected_versions',expected)
  or c.response is distinct from expected
  or(c.consumption_event_id,c.journal_id,c.materialization_id,c.journal_lines_sha256_pg)is distinct from
   (e.id,e.journal_id,o.id,e.lines_sha256_pg)
  or c.actual_manifest is distinct from manifest or c.actual_manifest_sha256<>cp7_credit.pg_jsonb_sha256(manifest)
  or c.final_native is distinct from o.before_native
  or o.quote_sha256<>cp7_credit.consumer_quote_binding_v1(q.payload,o.locked_sources,o.projection)
  or cp7_credit.consumer_verify_posted_journal_v1(o.id,e.journal_id)<>e.lines_sha256_pg then
  raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_COMPLETION_CHANGED';end if;
 if (select jsonb_agg(key order by key)from jsonb_object_keys(profiles)key)is distinct from cp7_credit_note_carry_de.active_sales_v1(o.source_graph)then
  raise exception 'CP7_CREDIT_CONSUMER_FINAL_INVOICE_SET_CHANGED';end if;
 for sale in select value from jsonb_array_elements_text(cp7_credit_note_carry_de.active_sales_v1(o.source_graph))order by value loop
  profile:=profiles->sale;before_profile:=o.locked_sources#>array['sources',sale,'profile'];
  native:=o.locked_sources#>array['sources',sale,'native'];
  select coalesce(sum((v->>'line_total')::numeric),0)into net from jsonb_array_elements(native->'items')v;
  net:=net-(select coalesce(sum((v->>'refund_amount')::numeric),0)from jsonb_array_elements(native->'return_items')v
   where exists(select 1 from jsonb_array_elements(native->'returns')r where r->>'id'=v->>'return_id'and r->>'status'='POSTED'));
  select coalesce(sum((v->>'amount')::numeric),0)into paid from jsonb_array_elements(native->'payments')v where v->>'status'='POSTED';
  issued:=(before_profile->>'I')::numeric;incoming:=(before_profile->>'U')::numeric;
  if sale=o.target_sale_id::text then incoming:=incoming+o.amount;end if;
  effective:=paid+incoming-issued;
  after_version:=(o.projection#>>array['expected_versions',sale])::bigint
   +case when sale in(o.source_current_leaf_id::text,o.target_current_leaf_id::text)then 1 else 0 end;
  if profile->>'sale_id'<>sale or(profile->>'row_version')::bigint is distinct from after_version
   or(profile->>'net')::numeric is distinct from net or(profile->>'P')::numeric is distinct from paid
   or(profile->>'U')::numeric is distinct from incoming or(profile->>'I')::numeric is distinct from issued
   or(profile->>'E')::numeric is distinct from effective or(profile->>'AR')::numeric is distinct from net-effective
   or profile->>'status'is distinct from(case when effective=net then'PAID'when effective>0 then'PARTIAL_PAID'else'POSTED'end)
   or net<0 or effective<0 or effective>net then raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_FINANCIAL_EFFECT_CHANGED';end if;
  perform cp7_credit.assert_financial_materialization_provenance(profile->'materialized');
  -- Current validation follows all retained signed events and every joint cut.
  perform cp7_credit_note_carry_de.validate_current_v1(sale::uuid);
 end loop;
 if c.final_profiles#>>'{source_capacity,source_prefixes_nonnegative}'is distinct from'true'
  or(c.final_profiles#>>'{source_capacity,current_balance}')::numeric is distinct from(o.projection#>>'{source_capacity_after,current_balance}')::numeric
  or(c.final_profiles#>>'{source_capacity,minimum_available}')::numeric is distinct from(o.projection#>>'{source_capacity_after,minimum_available}')::numeric then
  raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_CAPACITY_CHANGED';end if;
 if o.cash_coa_account_id is not null then
  if(c.final_profiles->>'cash_balance_after')::numeric is distinct from(o.projection->>'cash_balance_before')::numeric-o.amount then
   raise exception 'CP7_CREDIT_CONSUMER_HISTORICAL_CASH_EFFECT_CHANGED';end if;
 elsif c.final_profiles->>'cash_balance_after'is not null then raise exception 'CP7_CREDIT_CONSUMER_UNEXPECTED_CASH_EFFECT';end if;
 vectors:=cp7_credit.consumer_source_vectors_v1(o.cohort_id);
 capacity:=ow04_pure_kernel.credit_capacity_v1(vectors->'recognition',vectors->'consumptions',o.economic_date::text,o.transaction_date::text);
 if capacity->'source_prefixes_nonnegative'is distinct from'true'::jsonb then
  raise exception 'CP7_CREDIT_CONSUMER_CURRENT_HISTORICAL_JOINT_CAPACITY_UNFUNDED';end if;
 -- Leak checks are transaction facts, with no live-actor permission dependency.
 if exists(select 1 from cp7_credit.consumer_execution_context where backend_pid=pg_backend_pid()and transaction_id=txid_current())
  or exists(select 1 from cp7_credit.consumer_posting_scope_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current())then
  raise exception 'CP7_CREDIT_CONSUMER_TEMPORARY_SCOPE_NOT_CLEARED';end if;
end $$;

actual_functions.cp7_credit.consumer_dependency_graph_v1:
create function cp7_credit.consumer_dependency_graph_v1(p_sale uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare customer uuid;members uuid[];roots uuid[]:='{}';leaves uuid[]:='{}';
 cohorts uuid[];families uuid[];node uuid;a record;facts jsonb;answer jsonb;
begin
 select customer_id into strict customer from erp.sales_headers where id=p_sale;
 with recursive edges(a,b)as(
  select root_sale_id,previous_sale_id from cp7_note.revisions
  union select root_sale_id,replacement_sale_id from cp7_note.revisions
  union select f.family_root_sale_id,c.source_sale_id from cp7_credit.cohorts c
   join cp7_credit.return_families f on f.id=c.family_id
  union select f.family_root_sale_id,e.target_sale_id from cp7_credit.consumption_events e
   join cp7_credit.cohorts c on c.id=e.cohort_id
   join cp7_credit.return_families f on f.id=c.family_id
   where e.event_kind='APPLY'
 ),connected(id)as(
  select p_sale union
  select case when e.a=g.id then e.b else e.a end from connected g
   join edges e on e.a=g.id or e.b=g.id
 )select array_agg(id order by id)into members from connected;
 foreach node in array members loop
  select *into strict a from cp7_credit.current_leaf_assignment(node);
  if a.customer_id is distinct from customer then
   raise exception 'CP7_CREDIT_CONSUMER_GRAPH_CUSTOMER_CHANGED';end if;
  roots:=roots||a.root_sale_id;leaves:=leaves||a.current_leaf_id;
 end loop;
 select array_agg(distinct x order by x)into roots from unnest(roots)x;
 select array_agg(distinct x order by x)into leaves from unnest(leaves)x;
 select coalesce(array_agg(id order by id),'{}')into families
  from cp7_credit.return_families where family_root_sale_id=any(roots);
 select coalesce(array_agg(id order by id),'{}')into cohorts
  from cp7_credit.cohorts where family_id=any(families);
 if exists(select 1 from cp7_credit.cohorts c join cp7_credit.return_families f on f.id=c.family_id
  cross join lateral cp7_credit.current_leaf_assignment(c.source_sale_id)m
  where c.id=any(cohorts)and(c.customer_id is distinct from customer
   or m.root_sale_id is distinct from f.family_root_sale_id))then
  raise exception 'CP7_CREDIT_CONSUMER_GRAPH_COHORT_ROOT_CHANGED';end if;
 facts:=jsonb_build_object(
  'headers',(select coalesce(jsonb_agg(to_jsonb(h)order by h.id),'[]')from erp.sales_headers h where h.id=any(members)),
  'revisions',(select coalesce(jsonb_agg(to_jsonb(r)order by r.root_sale_id,r.revision),'[]')from cp7_note.revisions r where r.root_sale_id=any(roots)),
  'families',(select coalesce(jsonb_agg(to_jsonb(f)order by f.id),'[]')from cp7_credit.return_families f where f.id=any(families)),
  'cohorts',(select coalesce(jsonb_agg(to_jsonb(c)order by c.id),'[]')from cp7_credit.cohorts c where c.id=any(cohorts)),
  'consumptions',(select coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]')from cp7_credit.consumption_events e where e.cohort_id=any(cohorts)));
 answer:=jsonb_build_object('contract_version','ow04.consumer-dependency-graph.v1',
  'requested_sale_id',p_sale,'customer_id',customer,'sale_ids',members,
  'root_sale_ids',roots,'current_leaf_ids',leaves,'family_ids',families,'cohort_ids',cohorts,
  'facts',facts,'facts_sha256',cp7_credit.pg_jsonb_sha256(facts),
  'source_authority_proven',false,'all_signed_consumer_history_included',true);
 return answer;
end $$;

actual_functions.cp7_credit.consumer_joined_graph_v1:
create function cp7_credit.consumer_joined_graph_v1(p_source uuid,p_target uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare source_graph jsonb;target_graph jsonb;sales jsonb;
begin
 source_graph:=cp7_credit.consumer_dependency_graph_v1(p_source);
 if p_target is not null then
  target_graph:=cp7_credit.consumer_dependency_graph_v1(p_target);
  if target_graph->>'customer_id'is distinct from source_graph->>'customer_id'then
   raise exception 'CP7_CREDIT_CONSUMER_GRAPH_CUSTOMER_CHANGED';end if;
 end if;
 select jsonb_agg(v order by v)into sales from(select distinct value v from jsonb_array_elements_text(
  (source_graph->'sale_ids')||coalesce(target_graph->'sale_ids','[]')))all_ids;
 return jsonb_build_object('contract_version','ow04.consumer-joined-graph.v1','source',source_graph,
  'target',target_graph,'customer_id',source_graph->'customer_id','sale_ids',sales);
end $$;

actual_functions.cp7_credit.consumer_capture_sources_v1:
create function cp7_credit.consumer_capture_sources_v1(p_graph jsonb)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare sale uuid;sources jsonb:='{}';profile jsonb;
begin
 for sale in select value::uuid from jsonb_array_elements_text(cp7_credit_note_carry_de.active_sales_v1(p_graph))order by value loop
  perform cp7_credit.assert_current_materialized_profile(sale,cp7_credit_note_carry_de.root_v1(sale),sale);
  profile:=cp7_credit.inspect_current_materialized_profile(sale,cp7_credit_note_carry_de.root_v1(sale),sale);
  sources:=sources||jsonb_build_object(sale::text,jsonb_build_object('native',cp7_credit.source_native_snapshot_v1(sale),
   'profile',profile,'review_token',cp7_sales.review_token(sale)));
 end loop;
 return sources;
end $$;

actual_functions.cp7_credit.consumer_native_invariant_v1:
create function cp7_credit.consumer_native_invariant_v1(p_sale uuid)returns jsonb
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare native jsonb;events jsonb;journals jsonb;
begin
 native:=cp7_credit.source_native_snapshot_v1(p_sale);
 select coalesce(jsonb_agg(v order by v->>'id'collate"C"),'[]')into events
  from jsonb_array_elements(native->'base_events')v where not exists(select 1 from cp7_credit.consumption_events ce
   where ce.event_kind='APPLY'and cp7_credit_note_carry_de.effective_target_v1(ce.id)=p_sale and ce.journal_id=substring(v->>'id'from 9)::uuid);
 select coalesce(jsonb_agg(v order by v->>'id'collate"C"),'[]')into journals
  from jsonb_array_elements(native->'journals')v where not exists(select 1 from cp7_credit.consumption_events ce
   where ce.event_kind='APPLY'and cp7_credit_note_carry_de.effective_target_v1(ce.id)=p_sale and ce.journal_id=(v->>'id')::uuid);
 -- The opaque support hash contains ALLOCATION.sale including the very
 -- status/version/touch fields retired by this command. Raw allocations,
 -- items, movements, lots, HPP versions/caches/GL/targets remain exact here.
 -- The qualified source terminal proof makes the same distinction.
 return (native-'hpp_support')||jsonb_build_object('sale',(native->'sale')-'status'-'row_version'-'updated_at',
  'base_events',events,'journals',journals);
end $$;

actual_functions.cp7_credit.current_effective_paid:
create function cp7_credit.current_effective_paid(p_sale uuid)returns numeric
language plpgsql stable security definer set search_path=''set TimeZone='UTC'as $$
declare paid numeric;adjustment numeric;
begin
 select coalesce(sum(amount),0)into paid from erp.sales_payments where sale_id=p_sale and status='POSTED';
 adjustment:=erp._cp7_current_credit_adjustment(p_sale);
 if paid+adjustment<0 and not cp7_credit.payment_is_intermediate_v1(p_sale)then raise exception 'CP7_CREDIT_NEGATIVE_EFFECTIVE_PAID';end if;
 return paid+adjustment;
end $$;

native_callbacks.bump_row_version:
CREATE FUNCTION erp.bump_row_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'erp', 'public', 'pg_temp'
    AS $$
begin
  new.row_version := old.row_version + 1;
  return new;
end;
$$;

native_callbacks.touch_updated_at:
CREATE FUNCTION erp.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'erp', 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;
